create extension if not exists pgcrypto;
create table if not exists public.sensor_readings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,soil_moisture numeric(5,2) not null check(soil_moisture between 0 and 100),temperature numeric(5,2) not null,humidity numeric(5,2) not null check(humidity between 0 and 100),water_tank numeric(5,2) not null check(water_tank between 0 and 100),battery_level numeric(5,2) not null check(battery_level between 0 and 100),solar_voltage numeric(6,2) not null check(solar_voltage>=0),pump_on boolean not null default false,water_used_l numeric(10,2) not null default 0,created_at timestamptz not null default now());
create index if not exists sensor_readings_user_created_idx on public.sensor_readings(user_id,created_at desc);
create table if not exists public.device_state(user_id uuid primary key references auth.users(id) on delete cascade,mode text not null default 'auto' check(mode in('auto','manual')),pump_command boolean not null default false,moisture_low numeric(5,2) not null default 30 check(moisture_low between 0 and 95),moisture_high numeric(5,2) not null default 55 check(moisture_high between 5 and 100),updated_at timestamptz not null default now(),check(moisture_low<moisture_high));
create table if not exists public.disease_scans(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,image_url text,disease text not null,confidence numeric(6,5) not null,treatment text not null,created_at timestamptz not null default now());
create index if not exists disease_scans_user_created_idx on public.disease_scans(user_id,created_at desc);
create table if not exists public.alerts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,message text not null,resolved boolean not null default false,created_at timestamptz not null default now());
create index if not exists alerts_user_created_idx on public.alerts(user_id,created_at desc);
alter table public.sensor_readings enable row level security; alter table public.device_state enable row level security; alter table public.disease_scans enable row level security; alter table public.alerts enable row level security;
drop policy if exists "Users read own sensor readings" on public.sensor_readings; create policy "Users read own sensor readings" on public.sensor_readings for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Users read own device state" on public.device_state; create policy "Users read own device state" on public.device_state for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Users update own device state" on public.device_state; create policy "Users update own device state" on public.device_state for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "Users read own disease scans" on public.disease_scans; create policy "Users read own disease scans" on public.disease_scans for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Users read own alerts" on public.alerts; create policy "Users read own alerts" on public.alerts for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Users resolve own alerts" on public.alerts; create policy "Users resolve own alerts" on public.alerts for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
do $$ begin alter publication supabase_realtime add table public.sensor_readings; exception when duplicate_object then null; when undefined_object then null; end $$;
insert into storage.buckets(id,name,public) values('leaf-images','leaf-images',false) on conflict(id) do nothing;

-- Track pump start time so maximum runtime is enforced in automatic and manual modes.
alter table public.device_state add column if not exists pump_started_at timestamptz;
